/**
 * Word list generator for Word Battle
 * Generates comprehensive vocabulary JSON files for CET4, CET6, TOEFL, IELTS
 */

const fs = require('fs');
const path = require('path');

// Helper to write JSON file
function writeWordList(filename, words) {
  const filePath = path.join(__dirname, '..', 'src', 'data', 'words', filename);
  fs.writeFileSync(filePath, JSON.stringify(words, null, 2), 'utf8');
  console.log(`${filename}: ${words.length} words written`);
}

// Merge existing + new words, dedup by word field
function mergeWords(existingFile, newWords) {
  const filePath = path.join(__dirname, '..', 'src', 'data', 'words', existingFile);
  const existing = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  const existingSet = new Set(existing.map(w => w.word.toLowerCase()));
  const merged = [...existing];
  let added = 0;
  for (const w of newWords) {
    if (!existingSet.has(w.word.toLowerCase())) {
      merged.push(w);
      existingSet.add(w.word.toLowerCase());
      added++;
    }
  }
  console.log(`${existingFile}: ${existing.length} existing + ${added} new = ${merged.length} total`);
  return merged;
}

